    /// <summary>
    /// Middleware для логирования медленных HTTP-запросов в ASP.NET Core.
    /// </summary>
    public class SlowRequestLoggingMiddleware
    {
        private readonly RequestDelegate _next;
        private readonly ILogger<SlowRequestLoggingMiddleware> _logger;
        private readonly TimeSpan _slowRequestThreshold;

        /// <summary>
        /// Инициализирует новый экземпляр класса <see cref="SlowRequestLoggingMiddleware"/>.
        /// </summary>
        /// <param name="next">Следующий делегат в конвейере обработки запросов.</param>
        /// <param name="logger">Экземпляр логгера для записи сообщений.</param>
        /// <param name="slowRequestThreshold">Порог времени выполнения запроса, превышение которого считается "медленным". По умолчанию 500 мс.</param>
        public SlowRequestLoggingMiddleware(RequestDelegate next, ILogger<SlowRequestLoggingMiddleware> logger, TimeSpan? slowRequestThreshold = null)
        {
            _next = next ?? throw new ArgumentNullException(nameof(next));
            _logger = logger ?? throw new ArgumentNullException(nameof(logger));
            // Если порог не указан, используем значение по умолчанию — 500 миллисекунд
            _slowRequestThreshold = slowRequestThreshold ?? TimeSpan.FromMilliseconds(500);
        }

        /// <summary>
        /// Асинхронно обрабатывает входящий HTTP-запрос, измеряя время его выполнения.
        /// Если время выполнения превышает установленный порог, записывает предупреждение в лог.
        /// </summary>
        /// <param name="context">Контекст HTTP-запроса.</param>
        /// <returns>Задача, представляющая асинхронную операцию обработки запроса.</returns>
        public async Task InvokeAsync(HttpContext context)
        {
            // Создаём секундомер для измерения времени выполнения запроса
            var stopwatch = Stopwatch.StartNew();

            try
            {
                // Передаём управление следующему middleware в конвейере
                await _next(context);
            }
            finally
            {
                // Останавливаем секундомер после завершения обработки запроса
                stopwatch.Stop();

                // Получаем время выполнения запроса
                var elapsed = stopwatch.Elapsed;

                // Проверяем, превысило ли время выполнения установленный порог
                if (elapsed > _slowRequestThreshold)
                {
                    // Формируем сообщение с деталями медленного запроса
                    var message = $"Медленный запрос: {context.Request.Method} {context.Request.Path} " +
