// Task представляет собой функцию, которая будет выполнена воркером.
// Контекст позволяет отменить выполнение задачи при необходимости.
type Task func(ctx context.Context) error

// WorkerPool реализует пул воркеров с ограничением параллелизма.
// Пул принимает задачи из канала и распределяет их между фиксированным
// количеством воркеров. Количество одновременно выполняемых задач
// ограничено размером пула.
type WorkerPool struct {
	// tasks — канал, из которого воркеры забирают задачи для выполнения.
	tasks chan Task

	// wg — WaitGroup для ожидания завершения всех воркеров.
	wg sync.WaitGroup

	// ctx — контекст пула, который используется для отмены всех воркеров.
	ctx context.Context

	// cancel — функция отмены контекста пула.
	cancel context.CancelFunc

	// numWorkers — количество воркеров в пуле.
	numWorkers int

	// once — гарантирует, что пул будет запущен только один раз.
	once sync.Once

	// stopped — флаг, указывающий, что пул остановлен.
	stopped bool

	// mu — мьютекс для защиты поля stopped.
	mu sync.Mutex
}

// NewWorkerPool создаёт новый пул воркеров с указанным количеством воркеров.
// Параметры:
//   - numWorkers: количество воркеров (должно быть больше 0).
//   - bufferSize: размер буфера канала задач. Если равно 0, канал небуферизованный.
//
// Возвращает указатель на созданный пул.
func NewWorkerPool(numWorkers int, bufferSize int) *WorkerPool {
	if numWorkers <= 0 {
		numWorkers = 1
	}

	ctx, cancel := context.WithCancel(context.Background())

	return &WorkerPool{
		tasks:      make(chan Task, bufferSize),
		ctx:        ctx,
		cancel:     cancel,
		numWorkers: numWorkers,
	}
}

// Start запускает воркеры пула. Метод можно вызывать только один раз;
// повторные вызовы игнорируются. Каждый воркер бесконечно читает задачи
// из канала tasks и выполняет их до тех пор, пока канал не будет закрыт
// или контекст пула не будет отменён.
func (wp *WorkerPool) Start() {
	wp.once.Do(func() {
		for i := 0; i < wp.numWorkers; i++ {
			wp.wg.Add(1)
			go wp.worker()
		}
	})
}

