     * Интерфейс для определения размера значения в байтах.
     * Позволяет пользователю кэша указать, как измерять "память", занимаемую значением.
     */
    public interface SizeEstimator<V> {
        /**
         * Возвращает приблизительный размер объекта в байтах.
         *
         * @param value объект, размер которого нужно оценить
         * @return размер объекта в байтах
         */
        long sizeOf(V value);
    }

    /**
     * Узел двусвязного списка, хранящий пару ключ-значение.
     */
    private static class Node<K, V> {
        K key;
        V value;
        long size; // размер значения в байтах
        Node<K, V> prev;
        Node<K, V> next;

        Node(K key, V value, long size) {
            this.key = key;
            this.value = value;
            this.size = size;
        }
