//! Парсер аргументов командной строки для утилиты сжатия файлов.
//!
//! Этот модуль предоставляет структуру `CliArgs`, которая хранит распарсенные
//! аргументы командной строки, и функцию `parse_args`, которая выполняет
//! парсинг аргументов из `std::env::args()`.

use std::env;
use std::fmt;
use std::path::PathBuf;

/// Ошибки, которые могут возникнуть при парсинге аргументов командной строки.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseError {
    /// Неизвестный флаг или опция.
    UnknownFlag(String),
    /// Отсутствует обязательный аргумент (например, входной файл).
    MissingRequiredArgument(String),
    /// Неверное значение для опции (например, нечисловое значение для уровня сжатия).
    InvalidValue { flag: String, value: String },
    /// Дублирование опции, которая должна быть указана только один раз.
    DuplicateOption(String),
    /// Неверное использование позиционных аргументов.
    InvalidPositionalArgument(String),
}

impl fmt::Display for ParseError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ParseError::UnknownFlag(flag) => write!(f, "Неизвестный флаг: '{}'", flag),
            ParseError::MissingRequiredArgument(arg) => {
                write!(f, "Отсутствует обязательный аргумент: '{}'", arg)
            }
            ParseError::InvalidValue { flag, value } => {
                write!(f, "Неверное значение '{}' для опции '{}'", value, flag)
            }
            ParseError::DuplicateOption(opt) => {
                write!(f, "Опция '{}' указана более одного раза", opt)
            }
            ParseError::InvalidPositionalArgument(arg) => {
                write!(f, "Неверный позиционный аргумент: '{}'", arg)
            }
        }
    }
}

impl std::error::Error for ParseError {}

