public BigDecimal applyDiscount(BigDecimal price, int percent) {
    // Проверяем, что процент скидки находится в допустимом диапазоне от 0 до 100 включительно.
    // Если значение выходит за эти пределы, выбрасываем исключение IllegalArgumentException,
    // так как скидка не может быть отрицательной или превышать 100%.
    if (percent < 0 || percent > 100) throw new IllegalArgumentException("percent");

    // Вычисляем коэффициент скидки: (100 - percent) / 100.
    // Например, для скидки 20% коэффициент будет равен 0.8.
    // Используем BigDecimal.valueOf для точного представления чисел и избегаем проблем с плавающей точкой.
    BigDecimal k = BigDecimal.valueOf(100 - percent).divide(BigDecimal.valueOf(100));

    // Применяем скидку к исходной цене, умножая её на вычисленный коэффициент.
    // Затем устанавливаем масштаб (количество знаков после запятой) равным 2,
    // так как цены обычно имеют два десятичных знака (копейки/центы).
    // RoundingMode.HALF_EVEN (банковское округление) используется для минимизации систематической ошибки
    // при округлении, что является стандартной практикой в финансовых расчетах.
    return price.multiply(k).setScale(2, RoundingMode.HALF_EVEN);
}
