// Экспортируем функцию debounce, которая принимает функцию fn и задержку ms.
// Дженерик T ограничивает тип fn функцией, принимающей любые аргументы и возвращающей void.
export function debounce<T extends (...a: any[]) => void>(fn: T, ms: number) {
  // Переменная для хранения идентификатора таймера.
  // Инициализируется как undefined, чтобы показать, что таймер ещё не установлен.
  let timer: ReturnType<typeof setTimeout> | undefined;

  // Возвращаем новую функцию-обёртку, которая сохраняет сигнатуру оригинальной функции fn.
  // Parameters<T> извлекает типы аргументов из типа T, обеспечивая типобезопасность.
  return (...args: Parameters<T>) => {
    // Если таймер уже установлен (не undefined), отменяем предыдущий вызов setTimeout.
    // Это гарантирует, что fn будет выполнена только после последнего вызова обёртки.
    if (timer) clearTimeout(timer);

    // Устанавливаем новый таймер на выполнение fn через ms миллисекунд.
    // Аргументы args передаются в fn, сохраняя контекст вызова.
    timer = setTimeout(() => fn(...args), ms);
  };
}
```

