// Обобщённая функция для повторного выполнения блока кода при возникновении ошибок ввода-вывода
fun <T> retry(times: Int, block: () -> T): T {
    // Переменная для хранения последней пойманной ошибки, чтобы выбросить её после исчерпания попыток
    var last: Throwable? = null

    // Повторяем выполнение блока указанное количество раз
    repeat(times) {
        try {
            // Пытаемся выполнить переданный блок кода
            // Если выполнение успешно, сразу возвращаем результат и выходим из функции
            return block()
        } catch (e: IOException) {
            // Если произошла ошибка ввода-вывода, сохраняем её в переменную last
            // и продолжаем цикл для следующей попытки
            last = e
        }
    }

    // Если все попытки исчерпаны и ни одна не увенчалась успехом,
    // выбрасываем последнюю сохранённую ошибку.
    // Если ошибок не было (например, times == 0), выбрасываем IllegalStateException
    throw last ?: IllegalStateException("times must be > 0")
}
