// Get извлекает значение из кэша по указанному ключу.
//
// Метод потокобезопасен: использует блокировку на чтение (RLock) для доступа
// к внутреннему хранилищу элементов, что позволяет одновременное чтение
// несколькими горутинами.
//
// Поведение:
//   - Если ключ отсутствует в кэше, возвращается пустая строка и false.
//   - Если ключ найден, но срок жизни элемента (expires) истёк (текущее время
//     строго позже времени истечения), элемент считается недействительным,
//     и возвращаются пустая строка и false.
//   - Если ключ найден и срок жизни ещё не истёк, возвращается сохранённое
//     значение и true.
//
// Параметры:
//   - key: строковый ключ, по которому выполняется поиск элемента в кэше.
//     Пустая строка допустима как ключ, если она была ранее добавлена.
//
// Возвращаемые значения:
//   - string: значение, связанное с ключом, если элемент найден и не истёк;
//     пустая строка ("") в противном случае.
//   - bool: true, если элемент найден и действителен (не истёк);
//     false, если ключ отсутствует или элемент истёк.
//
// Граничные случаи:
//   - При одновременном чтении и записи (через другие методы, использующие
//     блокировку на запись) гарантируется консистентность данных благодаря
//     мьютексу sync.RWMutex.
//   - Проверка истечения срока выполняется после освобождения блокировки,
//     что допустимо, так как время истечения элемента неизменно после записи.
//   - Метод не удаляет истёкшие элементы из хранилища — очистка должна
//     выполняться отдельно (например, фоновым сборщиком или при записи).
//   - Если в кэше хранится пустая строка как значение, это неотличимо от
//     случая "ключ не найден" по возвращаемому значению string; однако
//     второй возвращаемый параметр bool позволяет точно определить, был ли
//     элемент найден и действителен.
//
// Пример использования:
//
//	value, found := cache.Get("user:123")
//	if found {
//	    fmt.Println("Значение:", value)
//	} else {
//	    fmt.Println("Элемент не найден или истёк")
//	}
func (c *Cache) Get(key string) (string, bool) {
	c.mu.RLock()
	e, ok := c.items[key]
	c.mu.RUnlock()
	if !ok || time.Now().After(e.expires) {
		return "", false
	}
	return e.value, true
}
```

