import java.util.concurrent.locks.ReentrantLock;

public class DeadlockExample {

    // Два ресурса (блокировки)
    private static final Lock lock1 = new ReentrantLock();
    private static final Lock lock2 = new ReentrantLock();

    public static void main(String[] args) {
        // Поток 1: сначала захватывает lock1, потом пытается захватить lock2
        Thread thread1 = new Thread(() -> {
            lock1.lock();
            System.out.println("Поток 1: захватил lock1, жду lock2...");
            try {
                Thread.sleep(100); // Имитация работы, чтобы дать время второму потоку
            } catch (InterruptedException e) {
                e.printStackTrace();
            }
            lock2.lock(); // Блокируется здесь, если lock2 занят
            System.out.println("Поток 1: захватил lock2");
            lock2.unlock();
            lock1.unlock();
        });

        // Поток 2: сначала захватывает lock2, потом пытается захватить

# 📸 UI Screenshot Comparator

Библиотека для автоматического сравнения скриншотов пользовательского интерфейса в UI-тестах. Позволяет обнаруживать визуальные регрессии, сравнивая эталонные изображения с текущими снимками экрана.

## 🎯 Назначение

Библиотека решает задачу **визуального регрессионного тестирования** (Visual Regression Testing) в UI-тестах. Она позволяет:

- Автоматически сравнивать скриншоты интерфейса с эталонными изображениями
- Обнаруживать визуальные изменения, которые не видны при проверке DOM-структуры
- Генерировать диффы (различия) между изображениями для быстрой диагностики
- Настраивать допустимый порог различий для борьбы с шумом (антиалиасинг, субпиксельное рендеринг)
- Интегрироваться с популярными фреймворками тестирования (Playwright, Puppeteer, Selenium, Cypress)

## 📦 Установка

### Через npm

```bash
npm install ui-screenshot-comparator
```

### Через yarn

```bash
yarn add ui-screenshot-comparator
```

### Через pnpm

```bash
pnpm add ui-screenshot-comparator
```

### Требования

- Node.js >= 16.0.0
- Для работы с изображениями требуется установленный `sharp` (устанавливается автоматически как зависимость)

## 💡 Пример использования

### Базовый пример с Playwright

```javascript
const { expect } = require('@playwright/test');
const { compareScreenshots } = require('ui-screenshot-comparator');

test('главная страница должна выглядеть корректно', async ({ page }) => {
  await page.goto('https://example.com');

  // Сделать скриншот и сравнить с эталоном
  const screenshot = await page.screenshot({ fullPage: true });

  const result = await compareScreenshots({
    current: screenshot,
    baseline: './screenshots/baseline/homepage.png',
    threshold: 0.1, // Допустимый процент различий (10%)
    outputDiff: './screenshots/diff/homepage-diff.png', // Путь для сохранения диффа
  });

  if (!result.passed) {
    console.log(`Визуальное различие: ${result.diffPercentage}%`);
    console.log(`Дифф сохранен в: ${result.diffPath}`);
    throw new Error('Визуальная регрессия обнаружена');
  }
});
```

